package main

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"unicode/utf8"
)

// SecureFileServer implements a file server with path-based authorization.
// It rejects non-ASCII paths entirely to avoid Unicode normalization issues.
type SecureFileServer struct {
	baseDir    string
	authToken  []byte
	acl        map[string][]string // cleaned path -> allowed roles
	mu         sync.RWMutex
}

func NewSecureFileServer(baseDir string, secret []byte) *SecureFileServer {
	if len(secret) < 32 {
		panic("secret must be at least 32 bytes")
	}
	absBase, err := filepath.Abs(baseDir)
	if err != nil {
		panic(err)
	}
	return &SecureFileServer{
		baseDir:   absBase,
		authToken: secret,
		acl:       make(map[string][]string),
	}
}

// SetACL sets the access control list entry for a path
func (s *SecureFileServer) SetACL(path string, roles []string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	cleaned := s.canonicalizePath(path)
	s.acl[cleaned] = roles
}

// isASCIIOnly returns true if the string contains only ASCII printable characters
// and forward slashes. This is a hard security boundary - we refuse to serve
// any path with non-ASCII characters to eliminate Unicode confusion attacks.
func isASCIIOnly(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] > 127 || s[i] < 32 {
			return false
		}
	}
	return true
}

// canonicalizePath cleans and lowercases the path for consistent comparison.
// Only called after isASCIIOnly validation, so no Unicode concerns.
func (s *SecureFileServer) canonicalizePath(reqPath string) string {
	cleaned := filepath.Clean(reqPath)
	cleaned = strings.ToLower(cleaned)
	return cleaned
}

// resolveFilePath resolves the actual filesystem path for serving.
func (s *SecureFileServer) resolveFilePath(reqPath string) (string, error) {
	cleaned := filepath.FromSlash(reqPath)
	cleaned = filepath.Clean(cleaned)
	fullPath := filepath.Join(s.baseDir, cleaned)
	absPath, err := filepath.Abs(fullPath)
	if err != nil {
		return "", fmt.Errorf("invalid path")
	}
	if !strings.HasPrefix(absPath, s.baseDir+string(os.PathSeparator)) && absPath != s.baseDir {
		return "", fmt.Errorf("path traversal detected")
	}
	return absPath, nil
}

// checkAuthorization verifies the user's role has access to the path.
// Uses the SAME canonicalized path for both ACL lookup and file resolution.
func (s *SecureFileServer) checkAuthorization(reqPath string, userRole string) bool {
	s.mu.RLock()
	defer s.mu.RUnlock()

	canonPath := s.canonicalizePath(reqPath)

	// Check exact match first
	if roles, ok := s.acl[canonPath]; ok {
		for _, r := range roles {
			if r == userRole {
				return true
			}
		}
		return false
	}

	// Check parent directory permissions
	dir := canonPath
	for dir != "." && dir != "/" && dir != "" {
		dir = filepath.Dir(dir)
		if roles, ok := s.acl[dir]; ok {
			for _, r := range roles {
				if r == userRole {
					return true
				}
			}
			return false
		}
	}

	return false
}

// verifyToken validates the HMAC authentication token
func (s *SecureFileServer) verifyToken(token string, userRole string) bool {
	parts := strings.SplitN(token, ":", 2)
	if len(parts) != 2 {
		return false
	}
	message := parts[0]
	providedMAC, err := hex.DecodeString(parts[1])
	if err != nil {
		return false
	}
	mac := hmac.New(sha256.New, s.authToken)
	mac.Write([]byte(message))
	expectedMAC := mac.Sum(nil)
	if !hmac.Equal(providedMAC, expectedMAC) {
		return false
	}
	msgParts := strings.SplitN(message, ":", 2)
	if len(msgParts) != 2 {
		return false
	}
	return msgParts[0] == userRole
}

// ServeHTTP handles file requests with authorization
func (s *SecureFileServer) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	authHeader := r.Header.Get("Authorization")
	roleHeader := r.Header.Get("X-User-Role")
	if authHeader == "" || roleHeader == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	if !s.verifyToken(authHeader, roleHeader) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	reqPath := r.URL.Path

	// Validate UTF-8
	if !utf8.ValidString(reqPath) {
		http.Error(w, "Invalid path encoding", http.StatusBadRequest)
		return
	}

	// SECURITY: Reject any non-ASCII path to prevent Unicode normalization attacks.
	// This is a deliberate hard cutoff - we only serve ASCII-named files.
	if !isASCIIOnly(reqPath) {
		http.Error(w, "Path contains invalid characters", http.StatusBadRequest)
		return
	}

	// Check authorization using canonicalized path
	if !s.checkAuthorization(reqPath, roleHeader) {
		http.Error(w, "Access denied", http.StatusForbidden)
		return
	}

	// Resolve actual file path
	filePath, err := s.resolveFilePath(reqPath)
	if err != nil {
		http.Error(w, "Invalid path", http.StatusBadRequest)
		return
	}

	data, err := ioutil.ReadFile(filePath)
	if err != nil {
		if os.IsNotExist(err) {
			http.Error(w, "Not found", http.StatusNotFound)
		} else {
			http.Error(w, "Internal error", http.StatusInternalServerError)
		}
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Write(data)
}

// loadSecret loads the HMAC secret from the environment. If not present,
// it generates a cryptographically random secret so tokens are never forgeable.
func loadSecret() []byte {
	if env := os.Getenv("FILE_SERVER_SECRET"); env != "" {
		secret, err := hex.DecodeString(env)
		if err != nil {
			panic("FILE_SERVER_SECRET must be hex-encoded")
		}
		if len(secret) < 32 {
			panic("FILE_SERVER_SECRET must be at least 32 bytes")
		}
		return secret
	}
	secret := make([]byte, 32)
	if _, err := rand.Read(secret); err != nil {
		panic(err)
	}
	return secret
}

func main() {
	secret := loadSecret()

	server := NewSecureFileServer("/var/data/files", secret)
	server.SetACL("/public", []string{"user", "admin"})
	server.SetACL("/private", []string{"admin"})
	server.SetACL("/private/reports", []string{"admin", "auditor"})

	http.Handle("/files/", http.StripPrefix("/files", server))
	fmt.Println("Starting secure file server on :8443")
	http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", nil)
}
